 public function storePhoneUsage(Request$r):JsonResponse{$this->enabled();$d=$r->validate(['phone_subscription_id'=>['required','uuid'],'staff_id'=>['required','uuid'],'period_start'=>['required','date'],'period_end'=>['required','date','after_or_equal:period_start'],'company_amount'=>['required','numeric','min:0'],'employee_excess_amount'=>['required','numeric','min:0'],'currency'=>['required','string','size:3'],'policy_snapshot'=>['required','array'],'source_checksum'=>['required','string','size:64']]);$sub=DB::table('hr_phone_subscriptions')->where('id',$d['phone_subscription_id'])->first();abort_unless($sub,404);$this->company($r,$sub->company_id);abort_unless(Staff::query()->whereKey($d['staff_id'])->where('company_id',$sub->company_id)->exists(),422);if($old=DB::table('hr_phone_usage_allocations')->where('phone_subscription_id',$sub->id)->where('period_start',$d['period_start'])->where('period_end',$d['period_end'])->first()){abort_unless(hash_equals($old->source_checksum,$d['source_checksum']),409,'Usage period was reused with different source evidence.');return response()->json(['status'=>'success','data'=>$old,'idempotent_replay'=>true]);}$id=(string)Str::uuid();$d['id']=$id;$d['company_id']=$sub->company_id;$d['currency']=strtoupper($d['currency']);$d['policy_snapshot']=json_encode($d['policy_snapshot'],JSON_THROW_ON_ERROR);$d['status']='pending_review';$d['created_at']=$d['updated_at']=now();DB::table('hr_phone_usage_allocations')->insert($d);return response()->json(['status'=>'success','data'=>DB::table('hr_phone_usage_allocations')->find($id)],201);}
 public function decidePhoneUsage(Request$r,string$id):JsonResponse{$this->enabled();$d=$r->validate(['decision'=>['required',Rule::in(['approved','disputed'])],'reason'=>['nullable','required_if:decision,disputed','string','max:2000']]);return DB::transaction(function()use($r,$id,$d){$u=DB::table('hr_phone_usage_allocations')->where('id',$id)->lockForUpdate()->first();abort_unless($u,404);$this->company($r,$u->company_id);abort_unless(in_array($u->status,['pending_review','disputed'],true),409);DB::table('hr_phone_usage_allocations')->where('id',$id)->update(['status'=>$d['decision'],'reviewed_by'=>$r->user()->id,'reviewed_at'=>now(),'dispute_reason'=>$d['reason']??null,'updated_at'=>now()]);if($d['decision']==='approved'){$payload=['phone_usage_allocation_id'=>$id,'staff_id'=>$u->staff_id,'company_amount'=>$u->company_amount,'employee_excess_amount'=>$u->employee_excess_amount,'currency'=>$u->currency,'source_checksum'=>$u->source_checksum];$outbox=(string)Str::uuid();DB::table('hr_accounting_outbox')->insert(['id'=>$outbox,'company_id'=>$u->company_id,'event_type'=>'phone_usage_allocation_approved','aggregate_type'=>'phone_usage_allocation','aggregate_id'=>$id,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'payload_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'status'=>'pending','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('hr_phone_usage_allocations')->where('id',$id)->update(['recovery_outbox_id'=>$outbox]);}return response()->json(['status'=>'success','data'=>DB::table('hr_phone_usage_allocations')->find($id)]);});}
 public function decideReturnException(Request$r,string$id):JsonResponse{$this->enabled();$d=$r->validate(['outcome'=>['required',Rule::in(['recovery_approved','exception_approved'])],'recovery_amount'=>['nullable','required_if:outcome,recovery_approved','numeric','min:0.01'],'currency'=>['nullable','required_if:outcome,recovery_approved','string','size:3'],'reason'=>['required','string','max:3000'],'evidence'=>['required','array']]);return DB::transaction(function()use($r,$id,$d){$c=DB::table('hr_custody_assignments')->where('id',$id)->lockForUpdate()->first();abort_unless($c,404);$this->company($r,$c->company_id);abort_unless($c->status==='exception_pending',409);abort_if($c->received_by===$r->user()->id,409,'The return receiver cannot approve the same exception.');DB::table('hr_custody_assignments')->where('id',$id)->update(['status'=>$d['outcome'],'updated_at'=>now()]);$this->custodyEvent($id,'exception_decided','exception_pending',$d['outcome'],null,null,$d['reason'],$r->user()->id,$d['evidence']);if($d['outcome']==='recovery_approved'){$payload=['custody_assignment_id'=>$id,'staff_id'=>$c->staff_id,'amount'=>$d['recovery_amount'],'currency'=>strtoupper($d['currency']),'action'=>'recover_asset_loss_or_damage'];DB::table('hr_accounting_outbox')->insert(['id'=>(string)Str::uuid(),'company_id'=>$c->company_id,'event_type'=>'asset_recovery_approved','aggregate_type'=>'custody_assignment','aggregate_id'=>$id,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'payload_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'status'=>'pending','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}return response()->json(['status'=>'success','data'=>DB::table('hr_custody_assignments')->find($id)]);});}
 private function requestEvent(string$id,string$type,?string$from,?string$to,array$e,string$actor):void{DB::table('hr_asset_request_events')->insert(['id'=>(string)Str::uuid(),'asset_request_id'=>$id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'evidence'=>json_encode($e,JSON_THROW_ON_ERROR),'actor_user_id'=>$actor,'occurred_at'=>now()]);}private function custodyEvent(string$id,string$type,?string$from,?string$to,?array$c,?array$a,?string$reason,string$actor,?array$e=null):void{DB::table('hr_custody_events')->insert(['id'=>(string)Str::uuid(),'custody_assignment_id'=>$id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'condition_snapshot'=>$c?json_encode($c,JSON_THROW_ON_ERROR):null,'accessory_snapshot'=>$a?json_encode($a,JSON_THROW_ON_ERROR):null,'reason'=>$reason,'evidence'=>$e?json_encode($e,JSON_THROW_ON_ERROR):null,'actor_user_id'=>$actor,'occurred_at'=>now()]);}private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function company(Request$r,string$id):void{abort_unless($this->actor($r)->company_id===$id,403,'Asset data is outside your legal entity.');}private function enabled():void{abort_unless(config('hr.features.advanced_assets',false),409,'Advanced HR asset writes are not enabled.');}
}
